# verify exact condition: exactly 2 copies of same-size uniform solid square of a minority color
def check(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    main=max(cnt,key=cnt.get)
    # collect all solid uniform squares >=2x2 of non-main colors
    sq=[]
    for c,col in [(i,j,g[i][j]) for i in range(H) for j in range(W)]:
        if col!=main:
            # flood fill of this color restricted to comp
            from collections import deque as dq
            seen={c};st=dq([c]);cells=[c]
            while st:
                y,x=st.popleft()
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        n=(y+dy,x+dx)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==col and n not in seen:
                            seen.add(n);st.dqappend(n);cells.append(n)
            s=set(cells)
            if len(s)==4 and max(i for i,j in s)-min(i for i,j in s)+1==2 and max(j for i,j in s)-min(j for i,j in s)+1==2:
                sq.append(col)
    uniq={}
    for col in sq: uniq.setdefault(col,[]).append(True)
    print('distinct sq colors',set(uniq))
    return len(uniq)==1
