def comps_of(g,col):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i2 in range(H):
        for j2 in range(W):
            if g[i2][j2]==col and not seen[i2][j2]:
                q=deque([(i2,j2)]); seen[i2][j2]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<H and 0<=xx<W and g[yy][xx]==col and not seen[yy][xx]:
                            seen[yy][xx]=True; q.append((yy,xx))
                out.append(cells)
    return out
def nbors(g,cc):
    H,W=len(g),len(g[0]); s=set()
    for y,x in cc:
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<H and 0<=xx<W: s.add(g[yy][xx])
    return s-{g[min(p[0] for p in cc)][min(p[1] for p in cc)]}
